impl crate::Payload for Payload {
    const TYPE_URI: &'static str = "https://trusttasks.org/spec/vta/dids/keys/list/1.0";
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\"$defs\":{\"ApprovalEvidenceKind\":{\"description\":\"The evidence an approval was recorded on, as `auth/step-up/approve-response` names it. Only the approver's own evidence is ever recorded: a proof by a key the VTA records as acting for an approver — a console signing key or any other delegation — is never an approval (CONVENTIONS.md §6.3).\",\"enum\":[\"didSigned\",\"webauthn\",\"approverSigned\"],\"title\":\"ApprovalEvidenceKind\",\"type\":\"string\"},\"DidMethodName\":{\"description\":\"The DID method an identity uses, as the method profile that governs it is named: `webvh` for a did:webvh identity, `scid:vh` for the did:scid:vh:1 form of one, `webs` for did:webs. Deliberately a pattern and not an enumeration: a method is added by publishing its profile under method-profiles/, never by changing this schema. A VTA MUST refuse a method it holds no profile for, or whose profile declares it ineligible, with `vta/dids:methodNotEligible`.\",\"pattern\":\"^[a-z0-9]+(:[a-z0-9]+)*$\",\"title\":\"DidMethodName\",\"type\":\"string\"},\"DidVerificationRelationship\":{\"description\":\"A DID Core verification relationship.\",\"enum\":[\"authentication\",\"assertionMethod\",\"keyAgreement\",\"capabilityInvocation\",\"capabilityDelegation\"],\"title\":\"DidVerificationRelationship\",\"type\":\"string\"},\"Ext\":{\"additionalProperties\":true,\"description\":\"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\"minProperties\":1,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"},\"title\":\"Ext\",\"type\":\"object\"},\"IdentityKeyCustody\":{\"additionalProperties\":false,\"description\":\"How a key is held. Present only in the custody projection. Carries no key material, and a conforming VTA MUST NOT place any in `ext`.\",\"properties\":{\"boundary\":{\"description\":\"Opaque, VTA-assigned label of the protection boundary holding the key (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised together. A recovery update key MUST carry a label different from every routine update key's. Custody projection only; never published.\",\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"custodian\":{\"$ref\":\"#/$defs/RecoveryCustodian\",\"description\":\"The recovery update key only: the kind of recovery custodian the operator declared when committing it (CONVENTIONS.md §5.6). Custody projection only; never published.\"},\"destroyed\":{\"description\":\"True once the private half has been destroyed — a retired `attestation` or `messaging` key. The record survives so the key's past signatures stay attributable.\",\"type\":\"boolean\"},\"exportable\":{\"description\":\"Whether the custodian would release the private half by any operation other than the VTA's own backup. Always `false` for `attestation` and `update` keys. Stated explicitly, never absent.\",\"type\":\"boolean\"},\"inBackups\":{\"description\":\"Whether the key, or material it can be re-derived or decrypted from, is in the VTA's backups or any state transfer. Always `false` for `attestation` and `update` keys of a level-3 identity (VTI-KEY-112); at level 2 such a key may be in the VTA's own backup and nowhere else (CONVENTIONS.md §5.5).\",\"type\":\"boolean\"},\"keyId\":{\"description\":\"The custodian record identifier (`keys/*`'s `keyId`) behind this key. Absent for a key this VTA does not hold (`protection: externalCustodian`).\",\"minLength\":1,\"type\":\"string\"},\"neverExportable\":{\"description\":\"True when no authority can make the key exportable. `true` implies `exportable: false`.\",\"type\":\"boolean\"},\"origin\":{\"$ref\":\"#/$defs/KeyOrigin\"},\"protection\":{\"$ref\":\"#/$defs/ProtectionClass\"}},\"required\":[\"exportable\",\"neverExportable\",\"inBackups\",\"protection\"],\"title\":\"IdentityKeyCustody\",\"type\":\"object\"},\"IdentityKeyRole\":{\"description\":\"The named key role a key occupies in an identity (CONVENTIONS.md §2; VTI-KEY-070 onward). `attestation` — the only keys in `assertionMethod`; sign the identity's attestation artefacts (credentials, endorsements, status lists) through the VTA's signing service and nowhere else. Generated inside the VTA, never derived, never exportable, never in a backup. `operational` — the only keys the identity's own process uses in `authentication`; sign the node's own traffic (Trust Task requests and responses, DIDComm and TSP signatures, invitations, notices, audit checkpoints). Derived. `messaging` — the only keys in `keyAgreement`; sign nothing. X25519, derived or generated in its own right and never converted from a signing key. `update` — the identifier's change authority as its DID method states it (a did:webvh log's `updateKeys` and `nextKeyHashes`, a KERI key event log's current and next keys); never a role-bound verification method, never in `keyRoles`. Generated inside the VTA, never derived, never exportable, never in a backup, and always accompanied by a committed recovery key held outside the VTA's protection boundary. `authenticator` — a key held on a person's own authenticator (a WebAuthn passkey), listed in `authentication` of that person's identity only; used only to verify the person's WebAuthn assertions (sign-in and step-up evidence) and never to accept a Data Integrity proof. The VTA never holds its private half, so it is enrolled by the passkey ceremony and never generated, added or rotated by these tasks. Never permitted on the durable identity of a VTA, a VTC or a VTN. No role permits `capabilityInvocation` or `capabilityDelegation` (VTI-KEY-075). The set is an extensible registry: a consumer that meets a role it does not implement MUST rely on the key for nothing, and MUST NOT map it onto a role it does know (VTI-KEY-074).\",\"enum\":[\"attestation\",\"operational\",\"messaging\",\"update\",\"authenticator\"],\"title\":\"IdentityKeyRole\",\"type\":\"string\"},\"IdentityRoleKey\":{\"additionalProperties\":false,\"description\":\"One key in one role. A key is in exactly one role for its whole life; a change of role is a retirement from one and an addition to another, with fresh material under a fresh identifier.\",\"properties\":{\"activatesAt\":{\"description\":\"For a `staged` key: when the VTA will begin using it — no earlier than the publishing change's cache horizon.\",\"format\":\"date-time\",\"type\":\"string\"},\"commitment\":{\"description\":\"For a `committed` update key: the commitment the identifier publishes (a did:webvh `nextKeyHashes` entry, a KERI next-key digest), in the method's own encoding.\",\"minLength\":1,\"type\":\"string\"},\"compromisedSince\":{\"description\":\"For a `revoked` key: the compromise time (VTI-KEY-121), published as the verification method's `revoked` value. Where it cannot be established, the time the key was first published.\",\"format\":\"date-time\",\"type\":\"string\"},\"custody\":{\"$ref\":\"#/$defs/IdentityKeyCustody\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"keyType\":{\"$ref\":\"#/$defs/KeyType\"},\"label\":{\"description\":\"Operator-facing label. Custody projection only.\",\"maxLength\":256,\"type\":\"string\"},\"publicKeyMultibase\":{\"description\":\"The public half, multibase-encoded, exactly as published. Absent for a `committed` update key, whose public half the identifier has not yet revealed.\",\"minLength\":1,\"type\":\"string\"},\"publishedInVersionId\":{\"description\":\"The method's version identifier of the change that first published the key or its commitment (method-profiles/: a did:webvh `versionId`, a KERI event's sequence number and digest). Absent while `pending`.\",\"type\":\"string\"},\"relationships\":{\"description\":\"The relationships the key is (or, while `pending`, will be) listed in: always exactly its role's one relationship. Empty for `update`, `retired` and `revoked` keys.\",\"items\":{\"$ref\":\"#/$defs/DidVerificationRelationship\"},\"type\":\"array\",\"uniqueItems\":true},\"removedInVersionId\":{\"description\":\"Version identifier of the change that retired or revoked the key.\",\"type\":\"string\"},\"retireAfter\":{\"description\":\"For a `retiring` key: the end of its overlap. Custody projection only.\",\"format\":\"date-time\",\"type\":\"string\"},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"rotationId\":{\"description\":\"The rotation this key was introduced or retired by.\",\"type\":\"string\"},\"state\":{\"$ref\":\"#/$defs/KeyLifecycleState\"},\"updateKeyClass\":{\"$ref\":\"#/$defs/UpdateKeyClass\"},\"verificationMethod\":{\"description\":\"The full verification-method identifier (`did#fragment`) the document publishes the key under and lists in `keyRoles`. Absent for `update` keys, which are never role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive its fragment from the key (VTI-KEY-150).\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"role\",\"keyType\",\"state\"],\"title\":\"IdentityRoleKey\",\"type\":\"object\"},\"KeyAssuranceLevel\":{\"description\":\"A service DID's key assurance level (VTI-KEY-194; CONVENTIONS.md §3.4). `1` — single key: no `keyRoles`, one key signs everything. `2` — role-separated: `keyRoles`, with the `attestation` and `update` keys held by the VTA, which may derive them and back them up. `3` — recoverable: level 2 with those keys generated and in no backup, a recovery key held by a recovery custodian outside the VTA, and a witness enforcing it. Declared in the document's `keyAssurance` member.\",\"enum\":[1,2,3],\"title\":\"KeyAssuranceLevel\",\"type\":\"integer\"},\"KeyChangeApprovalState\":{\"additionalProperties\":false,\"description\":\"Approval progress of a change the VTA's policy gates on approvals (CONVENTIONS.md §6).\",\"properties\":{\"approvals\":{\"description\":\"The approvals recorded. Custody projection only; omitted from a response to anyone who is not themselves an eligible approver of this change.\",\"items\":{\"$ref\":\"#/$defs/RecordedApproval\"},\"type\":\"array\"},\"expiresAt\":{\"description\":\"When the preview, and every approval bound to it, stops being usable.\",\"format\":\"date-time\",\"type\":\"string\"},\"received\":{\"description\":\"Distinct approvals recorded so far, the initiator's own included.\",\"minimum\":0,\"type\":\"integer\"},\"required\":{\"description\":\"Distinct approvals the VTA's policy requires.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"required\",\"received\",\"expiresAt\"],\"title\":\"KeyChangeApprovalState\",\"type\":\"object\"},\"KeyChangeKind\":{\"description\":\"`planned` — a successor was staged, activated, and the predecessor retired on the operator's schedule. `compromise` — a key was revoked and, where the role would otherwise be empty, replaced in the same change. `addition` — a key joined a role without anything leaving it. `recovery` — the identifier's update authority moved to the committed recovery key, because the VTA's own update keys were lost or may be in someone else's hands.\",\"enum\":[\"planned\",\"compromise\",\"addition\",\"recovery\"],\"title\":\"KeyChangeKind\",\"type\":\"string\"},\"KeyChangeRecord\":{\"additionalProperties\":false,\"description\":\"One change to a role's key set, from preview to completion. The identifier's history is the authority for what was published; this record adds which change was which and, in the custody projection, who asked, who approved, and why.\",\"properties\":{\"activatesAt\":{\"description\":\"When the successor becomes `active` and the predecessor `retiring`; never before `cacheHorizonAt`.\",\"format\":\"date-time\",\"type\":\"string\"},\"approvals\":{\"$ref\":\"#/$defs/KeyChangeApprovalState\"},\"autoRetire\":{\"description\":\"Custody projection only. Whether the VTA retires the predecessor itself at `overlapUntil`.\",\"type\":\"boolean\"},\"cacheHorizonAt\":{\"description\":\"Planned rotations: the publishing change's cache horizon (CONVENTIONS.md §10.1). The switch and any retirement happen no earlier.\",\"format\":\"date-time\",\"type\":\"string\"},\"endedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"endedInVersionId\":{\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"initiatedBy\":{\"description\":\"Custody projection only. VID of the administrator whose signed request started the change.\",\"type\":\"string\"},\"kind\":{\"$ref\":\"#/$defs/KeyChangeKind\"},\"overlapUntil\":{\"description\":\"Custody projection only. End of the overlap.\",\"format\":\"date-time\",\"type\":\"string\"},\"predecessors\":{\"description\":\"Verification-method identifiers (for `update`, public keys or commitments) leaving the role.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"reason\":{\"description\":\"Custody projection only. The operator's stated reason. Never published.\",\"maxLength\":1024,\"type\":\"string\"},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"rotationId\":{\"minLength\":1,\"type\":\"string\"},\"startedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"startedInVersionId\":{\"type\":\"string\"},\"state\":{\"$ref\":\"#/$defs/KeyChangeState\"},\"successors\":{\"description\":\"Verification-method identifiers (for `update`, public keys or commitments) entering the role.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"}},\"required\":[\"rotationId\",\"role\",\"kind\",\"state\"],\"title\":\"KeyChangeRecord\",\"type\":\"object\"},\"KeyChangeState\":{\"description\":\"`pendingApproval` — awaiting the approvals the VTA's policy requires; nothing is published. `awaitingRecoveryProof` — approved, and waiting for the recovery custodian's proof over the change; nothing is published. `staged` — successor published, not yet used. `overlapping` — successor active, predecessor `retiring`. `completed` — every predecessor retired, or the change is published and any overlap it began has ended. `aborted` — the successor was retired instead of the predecessor, or a revocation superseded the change. `expired` — the approvals or the recovery proof did not arrive before the preview expired; nothing was published.\",\"enum\":[\"pendingApproval\",\"awaitingRecoveryProof\",\"staged\",\"overlapping\",\"completed\",\"aborted\",\"expired\"],\"title\":\"KeyChangeState\",\"type\":\"string\"},\"KeyLifecycleState\":{\"description\":\"Where a key is in its role's lifecycle (CONVENTIONS.md §8, §10). `pending` — planned by a preview or a change awaiting approval; not published; custody projection only. `staged` — published and bound to its role but not yet used, until the publishing change's cache horizon. `active` — the key the VTA uses for new signatures (for `messaging`, advertises for new sessions; for `update`, the current authority). `retiring` — still published but never used to sign again; a retiring `messaging` key still decrypts until retirement. `retired` — removed by planned rotation; what it signed while published stays valid, judged against the identifier version current at issuance. `revoked` — withdrawn for compromise, recorded with `compromisedSince`; what it signed from then on establishes nothing. `committed` — an `update` key the identifier commits to as a successor but has not revealed (a did:webvh `nextKeyHashes` entry, a KERI next-key digest). `retired` and `revoked` are terminal.\",\"enum\":[\"pending\",\"staged\",\"active\",\"retiring\",\"retired\",\"revoked\",\"committed\"],\"title\":\"KeyLifecycleState\",\"type\":\"string\"},\"KeyListProjection\":{\"description\":\"Which view of the identity's key roles the caller was given (CONVENTIONS.md §11). `public` — only what the published identifier document and history already reveal. `custody` — additionally the VTA's custody state: pending keys, the custodian record and protection boundary behind each key, overlap deadlines, who initiated and approved each change, and why.\",\"enum\":[\"public\",\"custody\"],\"title\":\"KeyListProjection\",\"type\":\"string\"},\"KeyOrigin\":{\"default\":\"derived\",\"description\":\"Where the private key came from. `derived` means the maintainer generated it from a seed it holds and can reproduce it from `derivationPath`; `imported` means it arrived from outside and exists only as stored material; `internal` means the maintainer generated it from a CSPRNG and it is reproducible from nothing at all. The distinction is operationally load-bearing: a `derived` key survives a seed restore, an `imported` one is lost unless it was backed up separately, and an `internal` one cannot be recovered by any means once the maintainer's storage is gone. This member is also the only way a consumer can confirm that a `keys/create` request for an `internal` key was honoured rather than silently downgraded to a derived one — see that specification's `internal` member.\",\"enum\":[\"derived\",\"imported\",\"internal\"],\"title\":\"KeyOrigin\",\"type\":\"string\"},\"KeyRoleSummary\":{\"additionalProperties\":false,\"properties\":{\"keys\":{\"description\":\"The role's keys, in the order the document publishes them. Terminal-state keys are included only when the request asked for them, except a `revoked` key the document still lists, which is always included.\",\"items\":{\"$ref\":\"#/$defs/IdentityRoleKey\"},\"type\":\"array\"},\"recoveryCommitted\":{\"description\":\"`update` only: whether the identifier's latest version commits to a recovery key in a boundary other than the VTA's (CONVENTIONS.md §5.3). Always `true` at level 3, where `false` is a defect the VTA reports rather than hides; always `false` at level 2.\",\"type\":\"boolean\"},\"relationships\":{\"description\":\"The relationship this role owns. Empty for `update`.\",\"items\":{\"$ref\":\"#/$defs/DidVerificationRelationship\"},\"type\":\"array\",\"uniqueItems\":true},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"threshold\":{\"description\":\"`update` only, where the method has one: the signing threshold over the current update keys, in the method's own notation (a KERI `kt`).\",\"type\":\"string\"}},\"required\":[\"role\",\"relationships\",\"keys\"],\"title\":\"KeyRoleSummary\",\"type\":\"object\"},\"KeyType\":{\"description\":\"Cryptographic algorithm the key material belongs to. `ed25519` signs (EdDSA), `x25519` performs key agreement and never signs, `p256` signs (ES256), and `mldsa44` and `mldsa65` sign with the post-quantum ML-DSA scheme of US NIST FIPS 204. The set is expected to grow as algorithms are standardised, and growing it is a MINOR change under SPEC.md §5.2: `keyType` selects no schema branch, so adding a value relaxes a constraint rather than narrowing one, and the generated libraries mark this enumeration non-exhaustive so that a consumer absorbs a new value rather than failing to compile. Two ML-DSA parameter sets are carried because two specifications require different ones — W3C Quantum-Resistant Cryptosuites defines Data Integrity suites only for ML-DSA-44, while Trust Spanning Protocol Rev 3 §8.1 mandates ML-DSA-65 — so the parameter set is chosen by whatever consumes the key and the two are not redundant. A consumer that does not implement a value it receives MUST refuse the document rather than substitute one it does support.\",\"enum\":[\"ed25519\",\"x25519\",\"p256\",\"mldsa44\",\"mldsa65\"],\"title\":\"KeyType\",\"type\":\"string\"},\"ProtectionClass\":{\"description\":\"How a private half is protected (CONVENTIONS.md §5.2). `software` — stored by the VTA without encryption independent of the host (a plain VTA). `encryptedAtRest` — wrapped under a key the VTA holds outside its store (a hardened VTA). `enclave` — held only inside an attested trusted execution environment, wrapped under a key released only to its measurement (a TEE VTA). `hardwareModule` — held by a hardware security module or cloud key service that performs the operation without releasing the key. `externalCustodian` — not held by this VTA at all: a recovery update key, or an `authenticator` key on a person's device.\",\"enum\":[\"software\",\"encryptedAtRest\",\"enclave\",\"hardwareModule\",\"externalCustodian\"],\"title\":\"ProtectionClass\",\"type\":\"string\"},\"RecordedApproval\":{\"additionalProperties\":false,\"properties\":{\"approver\":{\"description\":\"VID of the approver.\",\"minLength\":1,\"type\":\"string\"},\"evidence\":{\"$ref\":\"#/$defs/ApprovalEvidenceKind\"},\"recordedAt\":{\"format\":\"date-time\",\"type\":\"string\"}},\"required\":[\"approver\",\"evidence\"],\"title\":\"RecordedApproval\",\"type\":\"object\"},\"RecoveryCustodian\":{\"additionalProperties\":false,\"description\":\"What the operator declares about who holds a recovery key. The VTA cannot verify it — it verifies the proof of possession and refuses a key it generated or can derive — and uses it to route a recovery signing request and to report custody. Custody projection only; never published (VTI-KEY-150, VTI-KEY-206).\",\"properties\":{\"did\":{\"description\":\"`vta` only: the custodian VTA's DID, to which the recovering or revoking VTA MAY send the recovery signing request. Absent, the request is carried out of band.\",\"minLength\":1,\"type\":\"string\"},\"kind\":{\"$ref\":\"#/$defs/RecoveryCustodianKind\"},\"participants\":{\"description\":\"`thresholdGroup` only: the participants' VTA DIDs, n of them. A threshold group has at least three participants, because 2 ≤ t < n (VTI-KEY-210).\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"minItems\":3,\"type\":\"array\",\"uniqueItems\":true},\"threshold\":{\"description\":\"`thresholdGroup` only: t, the number of participants that together sign. MUST be less than the number of `participants`.\",\"minimum\":2,\"type\":\"integer\"}},\"required\":[\"kind\"],\"title\":\"RecoveryCustodian\",\"type\":\"object\"},\"RecoveryCustodianKind\":{\"description\":\"The kinds of recovery custodian VTI-KEY-205 admits (CONVENTIONS.md §5.6). `separateKey` — a key held away from every VTA of the identity: an offline key file, a hardware token, a key service whose credentials no such VTA holds, or a key from a recovery mnemonic no such VTA has seen. `vta` — a second VTA with its own seed, operator and host. `thresholdGroup` — a threshold custodian: t of n VTAs holding FROST shares of the key (§5.7).\",\"enum\":[\"separateKey\",\"vta\",\"thresholdGroup\"],\"title\":\"RecoveryCustodianKind\",\"type\":\"string\"},\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"properties\":{\"assuranceLevel\":{\"$ref\":\"#/$defs/KeyAssuranceLevel\",\"description\":\"The key assurance level the identity's latest version declares, as a verifier would establish it (CONVENTIONS.md §3.4.3). In both projections: the document already publishes it.\"},\"did\":{\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"method\":{\"$ref\":\"#/$defs/DidMethodName\"},\"projection\":{\"$ref\":\"#/$defs/KeyListProjection\"},\"roles\":{\"description\":\"One entry per role asked for, including roles with no keys.\",\"items\":{\"$ref\":\"#/$defs/KeyRoleSummary\"},\"type\":\"array\"},\"rotations\":{\"description\":\"Present exactly when `includeHistory` was true. Newest first.\",\"items\":{\"$ref\":\"#/$defs/KeyChangeRecord\"},\"type\":\"array\"},\"versionId\":{\"description\":\"The version the answer describes. Pass it as `expectedVersionId` to a change made on its strength.\",\"type\":\"string\"}},\"required\":[\"did\",\"method\",\"versionId\",\"projection\",\"roles\"],\"title\":\"VTA DIDs — Keys List — response payload\",\"type\":\"object\"},\"UpdateKeyClass\":{\"description\":\"For an `update` key only (CONVENTIONS.md §5.3). `routine` — generated and held by the VTA, which authorizes the identity's ordinary changes with it. `recovery` — held by a recovery custodian in a protection boundary other than the VTA's; the VTA holds only its commitment, carries that commitment forward in every change it makes, and can use the key only by asking the custodian for a proof (`RecoverySigningRequest`).\",\"enum\":[\"routine\",\"recovery\"],\"title\":\"UpdateKeyClass\",\"type\":\"string\"}},\"$id\":\"https://trusttasks.org/spec/vta/dids/keys/list/1.0\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"List the key roles of a key-role identity a VTA holds keys for: each role's keys and their states, the update authority and recovery commitment, and optionally the rotation history, in the public or custody projection (CONVENTIONS.md §11).\",\"properties\":{\"did\":{\"description\":\"The key-role identity, by DID (for a `did:scid` identity, the DID without `src`).\",\"minLength\":1,\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"includeEnded\":{\"description\":\"Include `retired` and `revoked` keys. Absent reads as false. A `revoked` key the document still lists is always included.\",\"type\":\"boolean\"},\"includeHistory\":{\"description\":\"Include the rotation history. Absent reads as false.\",\"type\":\"boolean\"},\"roles\":{\"description\":\"Return only these roles. Absent returns every role. Present-but-empty is refused by the schema rather than read as 'every role'.\",\"items\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true}},\"required\":[\"did\"],\"title\":\"VTA DIDs — Keys List — payload\",\"type\":\"object\"}\n",
    );
}
impl crate::Payload for Response {
    const TYPE_URI: &'static str = "https://trusttasks.org/spec/vta/dids/keys/list/1.0#response";
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\"$defs\":{\"ApprovalEvidenceKind\":{\"description\":\"The evidence an approval was recorded on, as `auth/step-up/approve-response` names it. Only the approver's own evidence is ever recorded: a proof by a key the VTA records as acting for an approver — a console signing key or any other delegation — is never an approval (CONVENTIONS.md §6.3).\",\"enum\":[\"didSigned\",\"webauthn\",\"approverSigned\"],\"title\":\"ApprovalEvidenceKind\",\"type\":\"string\"},\"DidMethodName\":{\"description\":\"The DID method an identity uses, as the method profile that governs it is named: `webvh` for a did:webvh identity, `scid:vh` for the did:scid:vh:1 form of one, `webs` for did:webs. Deliberately a pattern and not an enumeration: a method is added by publishing its profile under method-profiles/, never by changing this schema. A VTA MUST refuse a method it holds no profile for, or whose profile declares it ineligible, with `vta/dids:methodNotEligible`.\",\"pattern\":\"^[a-z0-9]+(:[a-z0-9]+)*$\",\"title\":\"DidMethodName\",\"type\":\"string\"},\"DidVerificationRelationship\":{\"description\":\"A DID Core verification relationship.\",\"enum\":[\"authentication\",\"assertionMethod\",\"keyAgreement\",\"capabilityInvocation\",\"capabilityDelegation\"],\"title\":\"DidVerificationRelationship\",\"type\":\"string\"},\"Ext\":{\"additionalProperties\":true,\"description\":\"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\"minProperties\":1,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"},\"title\":\"Ext\",\"type\":\"object\"},\"IdentityKeyCustody\":{\"additionalProperties\":false,\"description\":\"How a key is held. Present only in the custody projection. Carries no key material, and a conforming VTA MUST NOT place any in `ext`.\",\"properties\":{\"boundary\":{\"description\":\"Opaque, VTA-assigned label of the protection boundary holding the key (CONVENTIONS.md §5.2). Two keys with the same label are lost or compromised together. A recovery update key MUST carry a label different from every routine update key's. Custody projection only; never published.\",\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"custodian\":{\"$ref\":\"#/$defs/RecoveryCustodian\",\"description\":\"The recovery update key only: the kind of recovery custodian the operator declared when committing it (CONVENTIONS.md §5.6). Custody projection only; never published.\"},\"destroyed\":{\"description\":\"True once the private half has been destroyed — a retired `attestation` or `messaging` key. The record survives so the key's past signatures stay attributable.\",\"type\":\"boolean\"},\"exportable\":{\"description\":\"Whether the custodian would release the private half by any operation other than the VTA's own backup. Always `false` for `attestation` and `update` keys. Stated explicitly, never absent.\",\"type\":\"boolean\"},\"inBackups\":{\"description\":\"Whether the key, or material it can be re-derived or decrypted from, is in the VTA's backups or any state transfer. Always `false` for `attestation` and `update` keys of a level-3 identity (VTI-KEY-112); at level 2 such a key may be in the VTA's own backup and nowhere else (CONVENTIONS.md §5.5).\",\"type\":\"boolean\"},\"keyId\":{\"description\":\"The custodian record identifier (`keys/*`'s `keyId`) behind this key. Absent for a key this VTA does not hold (`protection: externalCustodian`).\",\"minLength\":1,\"type\":\"string\"},\"neverExportable\":{\"description\":\"True when no authority can make the key exportable. `true` implies `exportable: false`.\",\"type\":\"boolean\"},\"origin\":{\"$ref\":\"#/$defs/KeyOrigin\"},\"protection\":{\"$ref\":\"#/$defs/ProtectionClass\"}},\"required\":[\"exportable\",\"neverExportable\",\"inBackups\",\"protection\"],\"title\":\"IdentityKeyCustody\",\"type\":\"object\"},\"IdentityKeyRole\":{\"description\":\"The named key role a key occupies in an identity (CONVENTIONS.md §2; VTI-KEY-070 onward). `attestation` — the only keys in `assertionMethod`; sign the identity's attestation artefacts (credentials, endorsements, status lists) through the VTA's signing service and nowhere else. Generated inside the VTA, never derived, never exportable, never in a backup. `operational` — the only keys the identity's own process uses in `authentication`; sign the node's own traffic (Trust Task requests and responses, DIDComm and TSP signatures, invitations, notices, audit checkpoints). Derived. `messaging` — the only keys in `keyAgreement`; sign nothing. X25519, derived or generated in its own right and never converted from a signing key. `update` — the identifier's change authority as its DID method states it (a did:webvh log's `updateKeys` and `nextKeyHashes`, a KERI key event log's current and next keys); never a role-bound verification method, never in `keyRoles`. Generated inside the VTA, never derived, never exportable, never in a backup, and always accompanied by a committed recovery key held outside the VTA's protection boundary. `authenticator` — a key held on a person's own authenticator (a WebAuthn passkey), listed in `authentication` of that person's identity only; used only to verify the person's WebAuthn assertions (sign-in and step-up evidence) and never to accept a Data Integrity proof. The VTA never holds its private half, so it is enrolled by the passkey ceremony and never generated, added or rotated by these tasks. Never permitted on the durable identity of a VTA, a VTC or a VTN. No role permits `capabilityInvocation` or `capabilityDelegation` (VTI-KEY-075). The set is an extensible registry: a consumer that meets a role it does not implement MUST rely on the key for nothing, and MUST NOT map it onto a role it does know (VTI-KEY-074).\",\"enum\":[\"attestation\",\"operational\",\"messaging\",\"update\",\"authenticator\"],\"title\":\"IdentityKeyRole\",\"type\":\"string\"},\"IdentityRoleKey\":{\"additionalProperties\":false,\"description\":\"One key in one role. A key is in exactly one role for its whole life; a change of role is a retirement from one and an addition to another, with fresh material under a fresh identifier.\",\"properties\":{\"activatesAt\":{\"description\":\"For a `staged` key: when the VTA will begin using it — no earlier than the publishing change's cache horizon.\",\"format\":\"date-time\",\"type\":\"string\"},\"commitment\":{\"description\":\"For a `committed` update key: the commitment the identifier publishes (a did:webvh `nextKeyHashes` entry, a KERI next-key digest), in the method's own encoding.\",\"minLength\":1,\"type\":\"string\"},\"compromisedSince\":{\"description\":\"For a `revoked` key: the compromise time (VTI-KEY-121), published as the verification method's `revoked` value. Where it cannot be established, the time the key was first published.\",\"format\":\"date-time\",\"type\":\"string\"},\"custody\":{\"$ref\":\"#/$defs/IdentityKeyCustody\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"keyType\":{\"$ref\":\"#/$defs/KeyType\"},\"label\":{\"description\":\"Operator-facing label. Custody projection only.\",\"maxLength\":256,\"type\":\"string\"},\"publicKeyMultibase\":{\"description\":\"The public half, multibase-encoded, exactly as published. Absent for a `committed` update key, whose public half the identifier has not yet revealed.\",\"minLength\":1,\"type\":\"string\"},\"publishedInVersionId\":{\"description\":\"The method's version identifier of the change that first published the key or its commitment (method-profiles/: a did:webvh `versionId`, a KERI event's sequence number and digest). Absent while `pending`.\",\"type\":\"string\"},\"relationships\":{\"description\":\"The relationships the key is (or, while `pending`, will be) listed in: always exactly its role's one relationship. Empty for `update`, `retired` and `revoked` keys.\",\"items\":{\"$ref\":\"#/$defs/DidVerificationRelationship\"},\"type\":\"array\",\"uniqueItems\":true},\"removedInVersionId\":{\"description\":\"Version identifier of the change that retired or revoked the key.\",\"type\":\"string\"},\"retireAfter\":{\"description\":\"For a `retiring` key: the end of its overlap. Custody projection only.\",\"format\":\"date-time\",\"type\":\"string\"},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"rotationId\":{\"description\":\"The rotation this key was introduced or retired by.\",\"type\":\"string\"},\"state\":{\"$ref\":\"#/$defs/KeyLifecycleState\"},\"updateKeyClass\":{\"$ref\":\"#/$defs/UpdateKeyClass\"},\"verificationMethod\":{\"description\":\"The full verification-method identifier (`did#fragment`) the document publishes the key under and lists in `keyRoles`. Absent for `update` keys, which are never role-bound verification methods (VTI-KEY-093). A VTA minting a method SHOULD derive its fragment from the key (VTI-KEY-150).\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"role\",\"keyType\",\"state\"],\"title\":\"IdentityRoleKey\",\"type\":\"object\"},\"KeyAssuranceLevel\":{\"description\":\"A service DID's key assurance level (VTI-KEY-194; CONVENTIONS.md §3.4). `1` — single key: no `keyRoles`, one key signs everything. `2` — role-separated: `keyRoles`, with the `attestation` and `update` keys held by the VTA, which may derive them and back them up. `3` — recoverable: level 2 with those keys generated and in no backup, a recovery key held by a recovery custodian outside the VTA, and a witness enforcing it. Declared in the document's `keyAssurance` member.\",\"enum\":[1,2,3],\"title\":\"KeyAssuranceLevel\",\"type\":\"integer\"},\"KeyChangeApprovalState\":{\"additionalProperties\":false,\"description\":\"Approval progress of a change the VTA's policy gates on approvals (CONVENTIONS.md §6).\",\"properties\":{\"approvals\":{\"description\":\"The approvals recorded. Custody projection only; omitted from a response to anyone who is not themselves an eligible approver of this change.\",\"items\":{\"$ref\":\"#/$defs/RecordedApproval\"},\"type\":\"array\"},\"expiresAt\":{\"description\":\"When the preview, and every approval bound to it, stops being usable.\",\"format\":\"date-time\",\"type\":\"string\"},\"received\":{\"description\":\"Distinct approvals recorded so far, the initiator's own included.\",\"minimum\":0,\"type\":\"integer\"},\"required\":{\"description\":\"Distinct approvals the VTA's policy requires.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"required\",\"received\",\"expiresAt\"],\"title\":\"KeyChangeApprovalState\",\"type\":\"object\"},\"KeyChangeKind\":{\"description\":\"`planned` — a successor was staged, activated, and the predecessor retired on the operator's schedule. `compromise` — a key was revoked and, where the role would otherwise be empty, replaced in the same change. `addition` — a key joined a role without anything leaving it. `recovery` — the identifier's update authority moved to the committed recovery key, because the VTA's own update keys were lost or may be in someone else's hands.\",\"enum\":[\"planned\",\"compromise\",\"addition\",\"recovery\"],\"title\":\"KeyChangeKind\",\"type\":\"string\"},\"KeyChangeRecord\":{\"additionalProperties\":false,\"description\":\"One change to a role's key set, from preview to completion. The identifier's history is the authority for what was published; this record adds which change was which and, in the custody projection, who asked, who approved, and why.\",\"properties\":{\"activatesAt\":{\"description\":\"When the successor becomes `active` and the predecessor `retiring`; never before `cacheHorizonAt`.\",\"format\":\"date-time\",\"type\":\"string\"},\"approvals\":{\"$ref\":\"#/$defs/KeyChangeApprovalState\"},\"autoRetire\":{\"description\":\"Custody projection only. Whether the VTA retires the predecessor itself at `overlapUntil`.\",\"type\":\"boolean\"},\"cacheHorizonAt\":{\"description\":\"Planned rotations: the publishing change's cache horizon (CONVENTIONS.md §10.1). The switch and any retirement happen no earlier.\",\"format\":\"date-time\",\"type\":\"string\"},\"endedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"endedInVersionId\":{\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"initiatedBy\":{\"description\":\"Custody projection only. VID of the administrator whose signed request started the change.\",\"type\":\"string\"},\"kind\":{\"$ref\":\"#/$defs/KeyChangeKind\"},\"overlapUntil\":{\"description\":\"Custody projection only. End of the overlap.\",\"format\":\"date-time\",\"type\":\"string\"},\"predecessors\":{\"description\":\"Verification-method identifiers (for `update`, public keys or commitments) leaving the role.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"reason\":{\"description\":\"Custody projection only. The operator's stated reason. Never published.\",\"maxLength\":1024,\"type\":\"string\"},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"rotationId\":{\"minLength\":1,\"type\":\"string\"},\"startedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"startedInVersionId\":{\"type\":\"string\"},\"state\":{\"$ref\":\"#/$defs/KeyChangeState\"},\"successors\":{\"description\":\"Verification-method identifiers (for `update`, public keys or commitments) entering the role.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"}},\"required\":[\"rotationId\",\"role\",\"kind\",\"state\"],\"title\":\"KeyChangeRecord\",\"type\":\"object\"},\"KeyChangeState\":{\"description\":\"`pendingApproval` — awaiting the approvals the VTA's policy requires; nothing is published. `awaitingRecoveryProof` — approved, and waiting for the recovery custodian's proof over the change; nothing is published. `staged` — successor published, not yet used. `overlapping` — successor active, predecessor `retiring`. `completed` — every predecessor retired, or the change is published and any overlap it began has ended. `aborted` — the successor was retired instead of the predecessor, or a revocation superseded the change. `expired` — the approvals or the recovery proof did not arrive before the preview expired; nothing was published.\",\"enum\":[\"pendingApproval\",\"awaitingRecoveryProof\",\"staged\",\"overlapping\",\"completed\",\"aborted\",\"expired\"],\"title\":\"KeyChangeState\",\"type\":\"string\"},\"KeyLifecycleState\":{\"description\":\"Where a key is in its role's lifecycle (CONVENTIONS.md §8, §10). `pending` — planned by a preview or a change awaiting approval; not published; custody projection only. `staged` — published and bound to its role but not yet used, until the publishing change's cache horizon. `active` — the key the VTA uses for new signatures (for `messaging`, advertises for new sessions; for `update`, the current authority). `retiring` — still published but never used to sign again; a retiring `messaging` key still decrypts until retirement. `retired` — removed by planned rotation; what it signed while published stays valid, judged against the identifier version current at issuance. `revoked` — withdrawn for compromise, recorded with `compromisedSince`; what it signed from then on establishes nothing. `committed` — an `update` key the identifier commits to as a successor but has not revealed (a did:webvh `nextKeyHashes` entry, a KERI next-key digest). `retired` and `revoked` are terminal.\",\"enum\":[\"pending\",\"staged\",\"active\",\"retiring\",\"retired\",\"revoked\",\"committed\"],\"title\":\"KeyLifecycleState\",\"type\":\"string\"},\"KeyListProjection\":{\"description\":\"Which view of the identity's key roles the caller was given (CONVENTIONS.md §11). `public` — only what the published identifier document and history already reveal. `custody` — additionally the VTA's custody state: pending keys, the custodian record and protection boundary behind each key, overlap deadlines, who initiated and approved each change, and why.\",\"enum\":[\"public\",\"custody\"],\"title\":\"KeyListProjection\",\"type\":\"string\"},\"KeyOrigin\":{\"default\":\"derived\",\"description\":\"Where the private key came from. `derived` means the maintainer generated it from a seed it holds and can reproduce it from `derivationPath`; `imported` means it arrived from outside and exists only as stored material; `internal` means the maintainer generated it from a CSPRNG and it is reproducible from nothing at all. The distinction is operationally load-bearing: a `derived` key survives a seed restore, an `imported` one is lost unless it was backed up separately, and an `internal` one cannot be recovered by any means once the maintainer's storage is gone. This member is also the only way a consumer can confirm that a `keys/create` request for an `internal` key was honoured rather than silently downgraded to a derived one — see that specification's `internal` member.\",\"enum\":[\"derived\",\"imported\",\"internal\"],\"title\":\"KeyOrigin\",\"type\":\"string\"},\"KeyRoleSummary\":{\"additionalProperties\":false,\"properties\":{\"keys\":{\"description\":\"The role's keys, in the order the document publishes them. Terminal-state keys are included only when the request asked for them, except a `revoked` key the document still lists, which is always included.\",\"items\":{\"$ref\":\"#/$defs/IdentityRoleKey\"},\"type\":\"array\"},\"recoveryCommitted\":{\"description\":\"`update` only: whether the identifier's latest version commits to a recovery key in a boundary other than the VTA's (CONVENTIONS.md §5.3). Always `true` at level 3, where `false` is a defect the VTA reports rather than hides; always `false` at level 2.\",\"type\":\"boolean\"},\"relationships\":{\"description\":\"The relationship this role owns. Empty for `update`.\",\"items\":{\"$ref\":\"#/$defs/DidVerificationRelationship\"},\"type\":\"array\",\"uniqueItems\":true},\"role\":{\"$ref\":\"#/$defs/IdentityKeyRole\"},\"threshold\":{\"description\":\"`update` only, where the method has one: the signing threshold over the current update keys, in the method's own notation (a KERI `kt`).\",\"type\":\"string\"}},\"required\":[\"role\",\"relationships\",\"keys\"],\"title\":\"KeyRoleSummary\",\"type\":\"object\"},\"KeyType\":{\"description\":\"Cryptographic algorithm the key material belongs to. `ed25519` signs (EdDSA), `x25519` performs key agreement and never signs, `p256` signs (ES256), and `mldsa44` and `mldsa65` sign with the post-quantum ML-DSA scheme of US NIST FIPS 204. The set is expected to grow as algorithms are standardised, and growing it is a MINOR change under SPEC.md §5.2: `keyType` selects no schema branch, so adding a value relaxes a constraint rather than narrowing one, and the generated libraries mark this enumeration non-exhaustive so that a consumer absorbs a new value rather than failing to compile. Two ML-DSA parameter sets are carried because two specifications require different ones — W3C Quantum-Resistant Cryptosuites defines Data Integrity suites only for ML-DSA-44, while Trust Spanning Protocol Rev 3 §8.1 mandates ML-DSA-65 — so the parameter set is chosen by whatever consumes the key and the two are not redundant. A consumer that does not implement a value it receives MUST refuse the document rather than substitute one it does support.\",\"enum\":[\"ed25519\",\"x25519\",\"p256\",\"mldsa44\",\"mldsa65\"],\"title\":\"KeyType\",\"type\":\"string\"},\"ProtectionClass\":{\"description\":\"How a private half is protected (CONVENTIONS.md §5.2). `software` — stored by the VTA without encryption independent of the host (a plain VTA). `encryptedAtRest` — wrapped under a key the VTA holds outside its store (a hardened VTA). `enclave` — held only inside an attested trusted execution environment, wrapped under a key released only to its measurement (a TEE VTA). `hardwareModule` — held by a hardware security module or cloud key service that performs the operation without releasing the key. `externalCustodian` — not held by this VTA at all: a recovery update key, or an `authenticator` key on a person's device.\",\"enum\":[\"software\",\"encryptedAtRest\",\"enclave\",\"hardwareModule\",\"externalCustodian\"],\"title\":\"ProtectionClass\",\"type\":\"string\"},\"RecordedApproval\":{\"additionalProperties\":false,\"properties\":{\"approver\":{\"description\":\"VID of the approver.\",\"minLength\":1,\"type\":\"string\"},\"evidence\":{\"$ref\":\"#/$defs/ApprovalEvidenceKind\"},\"recordedAt\":{\"format\":\"date-time\",\"type\":\"string\"}},\"required\":[\"approver\",\"evidence\"],\"title\":\"RecordedApproval\",\"type\":\"object\"},\"RecoveryCustodian\":{\"additionalProperties\":false,\"description\":\"What the operator declares about who holds a recovery key. The VTA cannot verify it — it verifies the proof of possession and refuses a key it generated or can derive — and uses it to route a recovery signing request and to report custody. Custody projection only; never published (VTI-KEY-150, VTI-KEY-206).\",\"properties\":{\"did\":{\"description\":\"`vta` only: the custodian VTA's DID, to which the recovering or revoking VTA MAY send the recovery signing request. Absent, the request is carried out of band.\",\"minLength\":1,\"type\":\"string\"},\"kind\":{\"$ref\":\"#/$defs/RecoveryCustodianKind\"},\"participants\":{\"description\":\"`thresholdGroup` only: the participants' VTA DIDs, n of them. A threshold group has at least three participants, because 2 ≤ t < n (VTI-KEY-210).\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"minItems\":3,\"type\":\"array\",\"uniqueItems\":true},\"threshold\":{\"description\":\"`thresholdGroup` only: t, the number of participants that together sign. MUST be less than the number of `participants`.\",\"minimum\":2,\"type\":\"integer\"}},\"required\":[\"kind\"],\"title\":\"RecoveryCustodian\",\"type\":\"object\"},\"RecoveryCustodianKind\":{\"description\":\"The kinds of recovery custodian VTI-KEY-205 admits (CONVENTIONS.md §5.6). `separateKey` — a key held away from every VTA of the identity: an offline key file, a hardware token, a key service whose credentials no such VTA holds, or a key from a recovery mnemonic no such VTA has seen. `vta` — a second VTA with its own seed, operator and host. `thresholdGroup` — a threshold custodian: t of n VTAs holding FROST shares of the key (§5.7).\",\"enum\":[\"separateKey\",\"vta\",\"thresholdGroup\"],\"title\":\"RecoveryCustodianKind\",\"type\":\"string\"},\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"properties\":{\"assuranceLevel\":{\"$ref\":\"#/$defs/KeyAssuranceLevel\",\"description\":\"The key assurance level the identity's latest version declares, as a verifier would establish it (CONVENTIONS.md §3.4.3). In both projections: the document already publishes it.\"},\"did\":{\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"method\":{\"$ref\":\"#/$defs/DidMethodName\"},\"projection\":{\"$ref\":\"#/$defs/KeyListProjection\"},\"roles\":{\"description\":\"One entry per role asked for, including roles with no keys.\",\"items\":{\"$ref\":\"#/$defs/KeyRoleSummary\"},\"type\":\"array\"},\"rotations\":{\"description\":\"Present exactly when `includeHistory` was true. Newest first.\",\"items\":{\"$ref\":\"#/$defs/KeyChangeRecord\"},\"type\":\"array\"},\"versionId\":{\"description\":\"The version the answer describes. Pass it as `expectedVersionId` to a change made on its strength.\",\"type\":\"string\"}},\"required\":[\"did\",\"method\",\"versionId\",\"projection\",\"roles\"],\"title\":\"VTA DIDs — Keys List — response payload\",\"type\":\"object\"},\"UpdateKeyClass\":{\"description\":\"For an `update` key only (CONVENTIONS.md §5.3). `routine` — generated and held by the VTA, which authorizes the identity's ordinary changes with it. `recovery` — held by a recovery custodian in a protection boundary other than the VTA's; the VTA holds only its commitment, carries that commitment forward in every change it makes, and can use the key only by asking the custodian for a proof (`RecoverySigningRequest`).\",\"enum\":[\"routine\",\"recovery\"],\"title\":\"UpdateKeyClass\",\"type\":\"string\"}},\"$ref\":\"#/$defs/Response\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\"}\n",
    );
}
impl crate::RequestPayload for Payload {
    type Response = Response;
}
/// The earlier `MAJOR.MINOR` of this slug that this version declares it
/// extends (front matter `extends`, SPEC §5.2 "Declared extension"), or
/// `None`. Only the direct declaration; walk a chain with
/// [`crate::extension::extends_for`].
pub const EXTENDS: Option<&str> = None;
/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::NOT_KEY_ROLE_IDENTITY,
    error_codes::METHOD_NOT_ELIGIBLE,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vta/dids:notFound`
    ///
    /// No such identity is held by this VTA, or the caller cannot reach its context.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/dids:notFound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/dids:notKeyRoleIdentity`
    ///
    /// The identity was not created with key roles. Create a new identity with key roles instead.
    ///
    /// Declared `retryable: false`.
    pub const NOT_KEY_ROLE_IDENTITY: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/dids:notKeyRoleIdentity",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/dids:methodNotEligible`
    ///
    /// The identity's method has no eligible profile.
    ///
    /// Declared `retryable: false`.
    pub const METHOD_NOT_ELIGIBLE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/dids:methodNotEligible",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
